// Sign the overdue-loans request the way convex/http.ts expects:
// signature = HMAC_SHA256(secret, `${timestamp}.GET./overdue-loans`)
const crypto = require('crypto');
const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', $env.LENDLOOP_SHARED_SECRET).update(`${timestamp}.GET./overdue-loans`).digest('hex');
return [{ json: { timestamp, signature } }];

// One item per overdue loan, with a per-day idempotency key so a re-run of
// this workflow (or an n8n retry) cannot create a duplicate reminder.
const today = new Date().toISOString().slice(0, 10);
const loans = $input.first().json.overdue || [];
return loans.map((loan) => ({ json: { ...loan, idempotencyKey: `${loan.loanId}:${today}:overdue-reminder` } }));

// SAFE DEFAULT: compose and log the reminder instead of emailing.
// To send for real, disable this node and enable 'Send Reminder Email
// (disabled)' with a genuine SMTP credential.
const out = [];
for (const item of $input.all()) {
  const loan = item.json;
  const message = `[LendLoop mock reminder] Hi ${loan.borrowerName}, "${loan.toolName}" was due back on ${loan.dueDate}. Please arrange its return. (No real email sent.)`;
  console.log(message);
  out.push({ json: { ...loan, reminderStatus: 'sent', channel: 'mock-email', message } });
}
return out;

// Build the write-back body and sign it: signature = HMAC(secret, `${ts}.${rawBody}`)
const crypto = require('crypto');
const out = [];
for (const item of $input.all()) {
  const loan = item.json;
  const body = JSON.stringify({ loanId: loan.loanId, borrowerEmail: loan.borrowerEmail, channel: loan.channel || 'mock-email', status: loan.reminderStatus || 'sent', idempotencyKey: loan.idempotencyKey });
  const timestamp = String(Date.now());
  const signature = crypto.createHmac('sha256', $env.LENDLOOP_SHARED_SECRET).update(`${timestamp}.${body}`).digest('hex');
  out.push({ json: { rawBody: body, timestamp, signature } });
}
return out;
